import sysconfig
from datetime import UTC, datetime
from pathlib import Path
from typing import Annotated

import msgspec
from clang.cindex import Cursor, CursorKind, TranslationUnit
from Cython.Tempita import Template
from typer import Typer

app = Typer()

PATH = Path(__file__).parent
CONFIG_FILE = PATH / "asyncio-config.toml"

CYTHON_PXD_FILE = Template("""

# This file is autogenerated as a safety mechanism
# incase asyncio.pxd is not found. Do not edit.

cdef extern from "asyncio_types.h":
    \"\"\"
/* part of {{path}}/asyncio_types.pxd */
typedef enum fut_state FutureState;
\"\"\"
    ctypedef enum FutureState:
        STATE_PENDING = 0
        STATE_CANCELLED = 1
        STATE_FINISHED = 2

    ctypedef struct FutureObj:
        pass

    ctypedef class _asyncio.Future [object FutureObj]:
        pass
    
    # Coming soon...
    # ctypedef class _asyncio.Task [object FutureObj]:
    #     pass

""")

# This tool is under concept but does work correctly on 3.11, 
# 3.9-3.10, 3.12-3.16 are not yet tested.

# This Tool allows _asyncio.Future objects to be safely exposed to Cython
# without the fear of segfaults occuring.

# You win
# - cdef extension classes for _asyncio.Future objects
# - an awaitable object with the best possible performance
# - all the object safety you could dream of with
#   minimized delays in performance.
# - You will have to make your own functions if you need to speed
#   things up, but for the most part this tool does the heavy-lifting
#   for you.

# Only disadvantage
# - it requires you to have _asyncio.pyd or _asyncio.so or any compiled
#   _asyncio module on hand but the rewards are well worth it.


# Dependencies are as follows
# msgspec, typer, libclang (if you want that .dll) / clang, cython (fast tempita)

# to use in your project place this in your tools directory
# it should be mapped as
# - tools/gen_object.py

# py tools/gen_object.py --help (etc...)

# to crate a new version simply downloading from the CPython repository
# https://github.com/Python/CPython should be enough.
# (Mainly involves downloading the zip files from each branch and then deleting them)

# This will likely make a handful of features seen in aiocapi obsolete.
# Aiocapi will likely adopt this little helper as a bonus.

HEADER_TEMPLATE = Template(
    """
#ifndef ___ASYNCIO_TYPES_H__
#define ___ASYNCIO_TYPES_H__

/* Generation Date: {{date}} */
/* Newest Supported Python Version: 3.{{highest}} */

#ifdef __cplusplus
extern "C" {
#endif

#include <Python.h>

{{for m in modules}}

#if (PY_MAJOR_VERSION == 3 && PY_MINOR_VERSION == {{m.minor}})
    #define CPYTHON_ASYNCIO_3{{m.minor}}
#endif

#ifdef CPYTHON_ASYNCIO_3{{m.minor}}

/* enums */
    {{for e in m.enums}}
typedef enum {{e.real_name}} {
        {{for v in e.values}}
    {{v.name}} = {{v.value}},
        {{endfor}}
} {{e.real_name}};
    {{endfor}}

/* structs */
{{for s in m.objects}}
typedef struct {{s.name}} {
    PyObject_HEAD
    {{for f in s.fields}}
    {{f.full_name}};
    {{endfor}}
} {{s.name}};
{{endfor}}

#endif /* 3.{{m.minor}} */

{{endfor}}


#if(PY_MAJOR_VERSION == 3 && PY_MINOR_VERSION < {{lowest}})
    #error "your version of python is not supported please upgrade to 3.{{lowest}} or higher"
#endif

#if(PY_MAJOR_VERSION == 3 && PY_MINOR_VERSION > {{highest}})
    #error "your version of python is not supported at the moment please throw an issue"
#endif

#ifdef __cplusplus
}
#endif /* __cplusplus */
#endif /* ___ASYNCIO_TYPES_H__ */
"""
)


class Tag(msgspec.Struct, tag=True):
    pass


class EnumValue(Tag):
    name: str
    value: int


class Enum(Tag):
    name: str
    values: list[EnumValue] = msgspec.field(default_factory=list)

    @property
    def real_name(self):
        """renames to get C to compile correcty."""
        # if self.name == "fut_state":
        #     return "FutureState"
        return self.name


class Field(Tag):
    name: str
    c_type: str

    @property
    def full_name(self) -> str:
        data = self.c_type.replace(" *", "*")
        data += f" {self.name}"
        return data


class Object(Tag):
    name: str
    fields: list[Field] = msgspec.field(default_factory=list)


class Module(Tag):
    minor: int
    version_hex: str
    objects: list[Object]
    enums: list[Enum]


class Edits(Tag):
    generated: Annotated[datetime, msgspec.Meta(tz=True)] = msgspec.field(
        default_factory=lambda: datetime.now(UTC)
    )
    modules: dict[str, Module] = msgspec.field(default_factory=dict)

    @property
    def sorted_modules(self):
        return [v for k, v in sorted(self.modules.items(), key=lambda m: m[1].minor)]

    @property
    def lowest(self) -> int:
        return min([m.minor for m in self.sorted_modules])

    @property
    def highest(self) -> int:
        return max([m.minor for m in self.sorted_modules])


def make_version_hex(major: int, minor: int, micro: int = 0):
    return (major << 24) | (minor << 16) | (micro << 8)


