PYTHON_INCLUDE_PATH = sysconfig.get_path("include")

# LLISTOBJECT is already a registered type so that we don't have to dig it up elsewhere.
# it won't be used in the cython project or exposed it's just a fill-in.
# will be using it when TaskObj is implemented.
LLLISTOBJECT = Object(
    "llist_node",
    [Field("next", "struct llist_node *"), Field("prev", "struct llist_node *")],
)


def get_translation_unit(source: Path, include: str):
    return TranslationUnit.from_source(source, [f"-I{include}"])


def extract_struct(cursor: Cursor):
    obj = Object(cursor.spelling)
    # Will be filling ob_base in when rewritten.
    obj.fields.extend(
        [
            Field(s.spelling, s.type.spelling)
            for s in cursor.type.get_fields()
            if s.spelling != "ob_base"
        ]
    )
    return obj


def extract_enum(node: Cursor) -> Enum:
    e = Enum(node.spelling)
    # Iterate over children to get enum constants
    for child in node.get_children():
        if child.kind == CursorKind.ENUM_CONSTANT_DECL:
            name = child.spelling
            # .enum_value property returns the integer value
            value = child.enum_value
            e.values.append(EnumValue(name, value))
    return e


def open_json() -> Edits:
    if CONFIG_FILE.exists():
        return msgspec.toml.decode(CONFIG_FILE.read_bytes(), type=Edits, strict=False)
    else:
        CONFIG_FILE.touch()
        return Edits()


def write_json(config: Edits):
    with CONFIG_FILE.open("wb") as w:
        w.write(b"\n\n# Automatically Generated File DO NOT EDIT!!!\n\n")
        w.write(msgspec.toml.encode(config))


@app.command()
def generate(source: Path, version_minor: int, include: str = PYTHON_INCLUDE_PATH):
    tu = get_translation_unit(source, include)
    cursor: Cursor = tu.cursor
    # most of people's copies of libclang from clang C++ library itself are very
    # lackluster and lack typehinting so you will see me doing a bunch of nasty recastings.
    data: list[Cursor] = [
        c
        for c in cursor.get_children()
        if c.kind == CursorKind.STRUCT_DECL and c.spelling in ["FutureObj"]
    ]

    enums: list[Cursor] = [
        c
        for c in cursor.get_children()
        if c.kind == CursorKind.ENUM_DECL and c.spelling in ["fut_state"]
    ]
    module = Module(
        version_minor,
        hex(make_version_hex(3, version_minor)),
        [extract_struct(s) for s in data],
        [extract_enum(e) for e in enums],
    )

    edits = open_json()
    if not edits.modules.get("3.9"):
        print("=== Adding Deprecated Releases ===")
        edits.modules.update(PRELOADED)
    edits.generated = datetime.now(UTC)
    edits.modules[f"3.{version_minor}"] = module
    write_json(edits)
    print(f"=== Saved edits for 3.{version_minor} ===")


@app.command()
def header(path: Path):
    """Generates asyncio_types.h file and cython asyncio_types.pxd"""
    edits = open_json()
    with (path / "asyncio_types.h").open("w") as w:
        w.write(
            HEADER_TEMPLATE.substitute(
                date=datetime.now(UTC),
                modules=edits.sorted_modules,
                lowest=edits.lowest,
                highest=edits.highest,
            )
        )

    print(f"=== Generated header at {path.as_posix()}/asyncio_types.h ===")

    with (path / "asyncio_types.pxd").open("w") as w:
        # windows paths are just annoying to look at so make it a posix path.
        w.write(CYTHON_PXD_FILE.substitute(path=path.as_posix()))

    print(f"=== Generated cython pxd file at {path.as_posix()}/asyncio_types.pxd ===")

if __name__ == "__main__":
    app()
